(() => {
  const $ = id => document.getElementById(id);
  const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]));
  const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9_./+<>=\-\s]/g,' ').replace(/\s+/g,' ').trim();
  const state = (()=>{try{return JSON.parse(localStorage.getItem('opsreadyV4')||'{}')}catch(e){return {}}})();
  state.best ||= {Architecture:{},Jinja:{},AgentDrills:{}}; state.history ||= [];
  const save = ()=>localStorage.setItem('opsreadyV4',JSON.stringify(state));
  const hasAny=(t,arr)=>arr.some(x=>norm(t).includes(norm(x)));
  const keywordScore=(text,groups,max)=>{if(!groups.length)return max;let hit=groups.filter(g=>hasAny(text,g)).length;return Math.round(max*hit/groups.length)};
  const record=(lab,id,title,score,detail)=>{state.best[lab] ||= {}; state.best[lab][id]=Math.max(state.best[lab][id]||0,score);state.history.push({lab,id,title,score,detail,at:new Date().toISOString()});state.history=state.history.slice(-80);save();renderMaster();try{parent.postMessage({type:'opsready-lab-score',lab:'V4 '+lab,score,detail:title+' — '+detail},'*')}catch(e){}};

  const architecture = [
    {id:'a1',title:'Relational 3 TB transformation already in Snowflake',domain:'Snowflake vs Spark',prompt:'A nightly 3 TB curated fact table already lives in Snowflake. Logic is joins, filters, windows and aggregations. BI consumes the result in Snowflake. Choose the primary transformation engine.',choices:['Snowflake SQL','PySpark on Databricks','Python pandas','Kafka Streams'],correct:'Snowflake SQL',why:[['data already in snowflake','warehouse','pushdown'],['sql','relational','window','join'],['avoid movement','no data movement','governance']],whyNot:[['spark','databricks'],['movement','operational complexity','extra platform']],trade:[['warehouse cost','credits','compute'],['query profile','pruning','spill']],proof:[['query profile','bytes scanned','pruning'],['runtime','sla'],['reconciliation','count','amount']],ref:'Use Snowflake SQL because the data and consumers are already in Snowflake and the workload is relational. PySpark adds movement and another runtime without a stateful/distributed requirement. Validate query profile, pruning, runtime, controls and credits.'},
    {id:'a2',title:'Stateful event-time dedupe with late arrivals',domain:'Spark Streaming vs SQL batch',prompt:'Kafka events arrive continuously, may be 20 minutes late, and duplicates must be suppressed before downstream reward effects. Choose the primary compute pattern.',choices:['PySpark Structured Streaming','Nightly Snowflake SQL','pandas batch','dbt snapshot'],correct:'PySpark Structured Streaming',why:[['stream','continuous','event time'],['watermark','state'],['dedupe','checkpoint']],whyNot:[['batch','nightly','latency'],['snowflake','sql']],trade:[['state','checkpoint','watermark'],['late','memory','recovery']],proof:[['input','processed','lag'],['duplicate','idempot'],['state','batch duration']],ref:'Use Structured Streaming for event-time state, watermarking and checkpointed continuous processing. Batch SQL misses the freshness requirement and cannot express the same streaming-state contract.'},
    {id:'a3',title:'Governed analytics models with tests and lineage',domain:'dbt vs PySpark',prompt:'Analysts need versioned SQL models, documentation, lineage, tests and semantic consistency over warehouse tables. Choose the primary transformation framework.',choices:['dbt','PySpark notebooks','Airflow operators only','FastAPI'],correct:'dbt',why:[['sql models','analytics'],['tests','lineage','docs'],['ref','source','semantic']],whyNot:[['pyspark','spark'],['notebook','extra runtime']],trade:[['sql centric','not streaming'],['warehouse cost','compile']],proof:[['dbt build','tests'],['lineage','docs'],['reconciliation','freshness']],ref:'Use dbt for warehouse-native analytical transformation, testing, documentation and lineage. PySpark is better when Spark-native distributed/stateful computation is actually required.'},
    {id:'a4',title:'Cross-platform orchestration',domain:'Airflow vs dbt',prompt:'A workflow must coordinate an API pull, Databricks job, Snowflake task, dbt build and post-deploy reconciliation with retries and SLAs.',choices:['Airflow','dbt only','Snowflake Dynamic Table','Kafka consumer group'],correct:'Airflow',why:[['orchestrat','dependency','workflow'],['retry','sla','schedule'],['api','databricks','snowflake','dbt']],whyNot:[['dbt','transformation'],['not orchestrator','cross platform']],trade:[['scheduler','operational overhead'],['idempot','retry']],proof:[['dag','task state'],['sla','retry'],['acceptance','reconciliation']],ref:'Airflow owns cross-system orchestration; dbt owns transformations and tests inside the analytics graph. Keep responsibilities separated.'},
    {id:'a5',title:'Snowflake-local CDC transformation',domain:'Streams + Tasks vs Airflow',prompt:'A Snowflake table receives inserts/updates and a small downstream table should process only changed rows every minute without leaving Snowflake.',choices:['Snowflake Streams + Tasks','Airflow full refresh','PySpark batch','pandas cron'],correct:'Snowflake Streams + Tasks',why:[['stream','change','cdc'],['task','snowflake local'],['incremental','minute']],whyNot:[['airflow','external'],['full refresh','overhead']],trade:[['stream staleness','retention'],['task graph','monitor']],proof:[['stream offset','has_data'],['task history'],['row counts','reconciliation']],ref:'Use Streams + Tasks for Snowflake-local CDC and scheduled processing. Airflow is useful when orchestration crosses systems, not merely to replace a native local primitive.'},
    {id:'a6',title:'Continuously refreshed warehouse-derived table',domain:'Dynamic Tables vs Tasks',prompt:'A derived Snowflake table should stay within a 5-minute freshness target and the team prefers declarative refresh management over hand-built task dependencies.',choices:['Snowflake Dynamic Table','Manual Streams + Tasks DAG','Kafka','FastAPI cache only'],correct:'Snowflake Dynamic Table',why:[['target lag','freshness'],['declarative','refresh'],['snowflake']],whyNot:[['task','manual','dependency'],['complexity']],trade:[['refresh cost','credits'],['supported query','target lag']],proof:[['refresh history','target lag'],['credits','cost'],['freshness','reconciliation']],ref:'Dynamic Tables are appropriate when the desired contract is declarative warehouse freshness. Tasks provide finer imperative control but require more orchestration logic.'},
    {id:'a7',title:'Mobile offer endpoint needs p95 under 150 ms',domain:'Serving store vs warehouse',prompt:'A mobile API currently runs a large Snowflake join per request and p95 is 4.8 seconds. Eligibility changes every few minutes.',choices:['Precomputed serving projection/cache','Scale Snowflake to 4XL','Run dbt on every request','pandas in API process'],correct:'Precomputed serving projection/cache',why:[['precompute','serving'],['latency','p95'],['cache','projection']],whyNot:[['snowflake','analytical warehouse'],['scale','cost']],trade:[['cache invalidation','stale'],['durable','source of truth']],proof:[['p95','p99','latency'],['freshness'],['correctness','redemption','reconciliation']],ref:'Separate analytical computation from low-latency serving. Precompute a governed projection/cache and preserve a durable authoritative state with explicit invalidation.'},
    {id:'a8',title:'High-throughput event transport with replay',domain:'Kafka vs batch files',prompt:'Casino telemetry arrives at 80K events/sec, multiple consumers need independent replayable streams, and ordering matters by machine.',choices:['Kafka','Hourly CSV files','dbt source freshness','Snowflake task only'],correct:'Kafka',why:[['event','stream'],['replay','offset'],['partition','ordering','consumer']],whyNot:[['file','hourly','latency'],['batch']],trade:[['partition','retention','ops'],['schema','consumer lag']],proof:[['lag','throughput'],['partition skew'],['replay','duplicate']],ref:'Kafka fits high-throughput replayable event transport with partitioned ordering. Batch files are simpler but violate latency and independent-consumer requirements.'},
    {id:'a9',title:'Small dimension joined to a huge fact',domain:'Broadcast vs shuffle',prompt:'A 40 MB property dimension is joined to a multi-terabyte fact table in Spark and the dimension is stable and unique.',choices:['Broadcast join','Repartition both to 4 partitions','collect() dimension to driver','Cartesian join then distinct'],correct:'Broadcast join',why:[['small dimension','broadcast'],['avoid shuffle','shuffle'],['fact','large']],whyNot:[['repartition','shuffle'],['collect','driver']],trade:[['memory','broadcast threshold'],['dimension growth']],proof:[['physical plan','broadcast'],['shuffle bytes'],['row count','cardinality']],ref:'Broadcast the genuinely small dimension to avoid shuffling the huge fact. Re-check size and uniqueness; switch when the dimension no longer fits executor memory safely.'},
    {id:'a10',title:'Two multi-terabyte tables must join',domain:'Shuffle/AQE vs broadcast',prompt:'Two large distributed datasets join on customer_id. Neither side is small enough to broadcast.',choices:['Partitioned shuffle join with AQE','Force broadcast','collect one table','Python nested loops'],correct:'Partitioned shuffle join with AQE',why:[['shuffle','partition'],['aqe','adaptive'],['large','distributed']],whyNot:[['broadcast','memory','oom'],['collect','driver']],trade:[['shuffle cost','skew'],['partition sizing']],proof:[['physical plan'],['shuffle read','spill'],['skew','runtime']],ref:'Use a distributed shuffle join with appropriate partitioning/AQE because neither side is safely broadcastable. Prove skew, spill and cardinality.'},
    {id:'a11',title:'Reduce output partitions after a narrow filter',domain:'coalesce vs repartition',prompt:'A Spark job filters 2 TB down to 12 GB and currently has 2,000 tiny output partitions. You only need to reduce partition count.',choices:['coalesce()','repartition() with full shuffle','collect()','cache() only'],correct:'coalesce()',why:[['reduce','partition'],['avoid shuffle','narrow']],whyNot:[['repartition','full shuffle'],['unnecessary']],trade:[['imbalance','skew'],['not increase','partition']],proof:[['file count','size'],['shuffle metrics'],['runtime']],ref:'coalesce is appropriate for reducing partitions with less shuffle. repartition is preferable when you need redistribution, an increase in partitions, or to repair skew.'},
    {id:'a12',title:'Redistribute skewed Spark data before expensive stage',domain:'repartition vs coalesce',prompt:'One partition holds 38% of rows before a wide aggregation. You need a more even distribution.',choices:['repartition() on a suitable key','coalesce()','collect()','single partition'],correct:'repartition() on a suitable key',why:[['redistribute','shuffle'],['skew','key'],['partition']],whyNot:[['coalesce','reduce only'],['does not rebalance','skew']],trade:[['shuffle cost'],['key choice','partition count']],proof:[['partition sizes','skew'],['shuffle','spill'],['runtime']],ref:'repartition intentionally shuffles to rebalance or repartition by key. coalesce does not solve this distribution problem.'},
    {id:'a13',title:'Simple transformation expressible with Spark built-ins',domain:'Native expression vs Python UDF',prompt:'You need to normalize strings, conditional flags and timestamps in PySpark. All logic exists in Spark SQL functions.',choices:['Native Spark expressions','Python UDF','collect to pandas','REST API per row'],correct:'Native Spark expressions',why:[['catalyst','optimizer'],['native','spark'],['serialization','avoid udf']],whyNot:[['python udf','serialization'],['optimizer','black box']],trade:[['expressiveness'],['built in']],proof:[['physical plan'],['runtime'],['cpu','serialization']],ref:'Prefer native Spark expressions so Catalyst can optimize and execution stays in the JVM/vectorized path. Use UDFs only when required logic cannot be expressed safely with native functions.'},
    {id:'a14',title:'Retry-safe reward sink',domain:'MERGE vs append',prompt:'A streaming micro-batch may retry after the sink commits. The business invariant is one reward effect per reward_id.',choices:['Idempotent MERGE on deterministic key','Append every retry','TRUNCATE and reload','DISTINCT in dashboard'],correct:'Idempotent MERGE on deterministic key',why:[['idempot','retry'],['merge','key'],['one business effect','duplicate']],whyNot:[['append','duplicate'],['distinct','hides']],trade:[['merge cost','concurrency'],['key design']],proof:[['duplicate','unique key'],['replay','same batch'],['reconciliation']],ref:'Use deterministic keys and idempotent MERGE so replay cannot create a second business effect. DISTINCT downstream hides corruption rather than preventing it.'},
    {id:'a15',title:'Historical customer tier must be reproducible',domain:'SCD2 vs overwrite',prompt:'Analytics must answer what tier a player had when a transaction happened six months ago.',choices:['SCD Type 2','Overwrite current tier','Cache current value only','Delete old versions'],correct:'SCD Type 2',why:[['history','point in time','as of'],['effective','valid from','valid to']],whyNot:[['overwrite','loses history'],['current only']],trade:[['storage','join complexity'],['effective dates']],proof:[['no overlap','one active'],['as of join'],['history reconciliation']],ref:'Use SCD2 when historical point-in-time truth matters. Current-state overwrite is simpler but destroys the past state required by the business question.'},
    {id:'a16',title:'Score 40 million customers nightly',domain:'Batch scoring vs API scoring',prompt:'A propensity model must score the entire customer base by 5 AM. No interactive request needs a score.',choices:['Batch scoring pipeline','One HTTP request per customer','Synchronous FastAPI only','Manual notebook loop'],correct:'Batch scoring pipeline',why:[['batch','throughput'],['40 million','bulk'],['sla','5 am']],whyNot:[['api','per request','overhead'],['latency not needed']],trade:[['freshness','schedule'],['compute window']],proof:[['throughput','completion'],['model version'],['row count','distribution']],ref:'Use distributed batch scoring for bulk throughput and reproducibility. Online API scoring is for request-time decisions where low latency is required.'},
    {id:'a17',title:'Validate pure Python retry/backoff logic',domain:'pytest vs dbt tests',prompt:'You need deterministic unit tests for a Python function that handles 429 responses, exponential backoff and max retries.',choices:['pytest','dbt generic test','Snowflake task','dashboard QA'],correct:'pytest',why:[['python','unit'],['mock','429','retry'],['deterministic']],whyNot:[['dbt','data model','sql'],['not python']],trade:[['mock realism','integration'],['unit vs integration']],proof:[['assert','attempts','sleep'],['exception'],['coverage']],ref:'Use pytest for Python behavior and mocks. dbt tests validate data/model contracts, not Python control-flow implementation.'},
    {id:'a18',title:'Validate uniqueness and not-null on a dbt model',domain:'dbt test vs pytest',prompt:'customer_id must be unique and not null in a warehouse model built by dbt.',choices:['dbt generic tests','pytest only','Kafka consumer test','FastAPI response model'],correct:'dbt generic tests',why:[['unique','not null'],['dbt','model'],['generic test','yaml']],whyNot:[['pytest','python'],['warehouse data contract']],trade:[['warehouse scan','cost'],['test severity']],proof:[['dbt test','fail rows'],['ci','build']],ref:'Use dbt generic tests for reusable column/model assertions such as unique and not_null. pytest remains appropriate for Python code.'},
    {id:'a19',title:'Complex cross-table financial reconciliation rule',domain:'singular vs generic dbt test',prompt:'A model must prove source dollars = accepted + rejected + adjustments across several tables with business-specific logic.',choices:['dbt singular SQL test','generic unique test','Python UDF','source freshness only'],correct:'dbt singular SQL test',why:[['business specific','reconciliation'],['sql test','returns failing rows'],['cross table']],whyNot:[['generic','simple reusable'],['unique','not enough']],trade:[['maintenance','complex sql'],['cost']],proof:[['zero failing rows'],['residual','control total']],ref:'Use a singular test for business-specific cross-table reconciliation. Generic tests are best for reusable assertions such as uniqueness, nullability and relationships.'},
    {id:'a20',title:'Files land continuously in cloud storage',domain:'Snowpipe vs Kafka',prompt:'Partners drop immutable JSON files into cloud object storage. Near-real-time warehouse ingestion is needed, but there is no event-stream producer contract.',choices:['Snowpipe / file-triggered ingestion','Kafka first','Manual COPY once daily','FastAPI upload loop'],correct:'Snowpipe / file-triggered ingestion',why:[['files','object storage'],['snowpipe','copy','near real time'],['event notification']],whyNot:[['kafka','producer','stream contract'],['unnecessary']],trade:[['file size','cost'],['schema','error handling']],proof:[['load history'],['latency'],['rejects','counts']],ref:'Use file-native continuous ingestion when the source contract is object-store files. Kafka is appropriate when the source is an event stream and replay/consumer semantics are required.'},
    {id:'a21',title:'Deterministic policy calculation with strict auditability',domain:'Agent vs deterministic code',prompt:'A regulated fee calculation has fixed rules and must produce the same output for the same inputs. No ambiguous reasoning is required.',choices:['Deterministic code/rules engine','LLM agent decides fee','Conversational analytics agent','Autonomous self-healing agent'],correct:'Deterministic code/rules engine',why:[['deterministic','same input'],['audit','rules'],['regulated','fixed']],whyNot:[['agent','llm'],['nondetermin','unnecessary']],trade:[['flexibility','rule maintenance'],['versioning']],proof:[['unit tests','golden cases'],['version','audit'],['reconciliation']],ref:'Do not use an agent where deterministic code is sufficient. Agents add probabilistic behavior and governance burden; reserve them for tasks needing interpretation, tool selection or bounded reasoning.'},
    {id:'a22',title:'Natural-language analytics over governed metrics',domain:'Agent vs dashboard',prompt:'Executives ask ad-hoc natural-language questions across approved semantic metrics. Responses must cite metric definitions and must not write data.',choices:['Read-only conversational analytics agent','Unrestricted SQL agent with admin role','Hard-code every possible dashboard','Autonomous mutation agent'],correct:'Read-only conversational analytics agent',why:[['natural language','ad hoc'],['semantic','governed'],['read only','select']],whyNot:[['admin','write','risk'],['dashboard','fixed']],trade:[['hallucination','guardrail'],['latency','cost']],proof:[['allowlist','semantic view'],['sql validation','citations'],['audit log']],ref:'A bounded read-only analytics agent is appropriate because the task requires language interpretation over governed metrics. Its tools and authority must be restricted and auditable.'},
    {id:'a23',title:'Top 3 earners per department',domain:'QUALIFY vs nested subquery',prompt:'In Snowflake, rank employees within each department and keep the top 3 with concise readable SQL.',choices:['Window function + QUALIFY','GROUP BY only','Correlated DELETE','Python loop'],correct:'Window function + QUALIFY',why:[['window','rank','dense_rank','row_number'],['qualify'],['partition by']],whyNot:[['group by','loses row detail'],['subquery','more verbose']],trade:[['snowflake specific','portability'],['ties']],proof:[['department','top 3'],['tie behavior'],['row counts']],ref:'Snowflake QUALIFY filters window-function results directly and is concise. A nested CTE/subquery is more portable, so portability is the main tradeoff.'},
    {id:'a24',title:'Reusable intermediate result referenced many times',domain:'CTE vs temporary table',prompt:'A heavy intermediate result is reused across several subsequent statements in the same operational workflow and you need to inspect it independently.',choices:['Temporary/transient staging table','Repeat the CTE in every statement','Python list','Kafka topic'],correct:'Temporary/transient staging table',why:[['reuse','multiple statements'],['materialize','inspect'],['intermediate']],whyNot:[['cte','statement scope','recompute'],['repeat']],trade:[['storage','cleanup'],['lifecycle']],proof:[['query history','runtime'],['row count'],['cleanup']],ref:'A temporary/transient staging table can be appropriate when a costly intermediate result must be reused and inspected across statements. CTEs are excellent for single-statement readability but do not inherently materialize reusable state.'}
  ];

  const jinja = [
    {id:'j1',title:'Use ref() instead of hard-coded relation',level:'Core',prompt:'Build int_rewards from stg_reward_events using dbt dependency resolution.',starter:"select *\nfrom analytics.stg_reward_events",req:[['{{ ref','ref('],['stg_reward_events']],anti:[['analytics.stg_reward_events','hard-coded database/schema']],why:[['lineage','dependency','environment'],['ref']],ref:"select *\nfrom {{ ref('stg_reward_events') }}"},
    {id:'j2',title:'Use source() for governed raw input',level:'Core',prompt:'Reference the declared raw loyalty source named loyalty.reward_events.',starter:"select * from RAW.LOYALTY.REWARD_EVENTS",req:[['{{ source','source('],['loyalty'],['reward_events']],anti:[['RAW.LOYALTY','hard-coded source']],why:[['source','freshness','lineage']],ref:"select *\nfrom {{ source('loyalty', 'reward_events') }}"},
    {id:'j3',title:'Correct incremental guard',level:'Core',prompt:'Add an incremental-only WHERE clause with a six-hour lookback against {{ this }}.',starter:"{{ config(materialized='incremental', unique_key='event_id') }}\n\nselect * from {{ ref('stg_events') }}\n\n{% if is_incremental %}\nwhere event_ts > (select max(event_ts) from {{ this }})\n{% endif %}",req:[['is_incremental()'],['{{ this }}'],['dateadd','interval'],['-6','6 hour']],anti:[['is_incremental %}','is_incremental must be called'],['> (select max','strict max misses late events']],why:[['late','lookback','incremental'],['idempot','unique key']],ref:"{{ config(materialized='incremental', unique_key='event_id') }}\n\nselect *\nfrom {{ ref('stg_events') }}\n{% if is_incremental() %}\nwhere event_ts >= dateadd(hour,-6,(select max(event_ts) from {{ this }}))\n{% endif %}"},
    {id:'j4',title:'Parameterize lookback with var()',level:'Intermediate',prompt:'Replace a hard-coded 6-hour lookback with a project variable named lookback_hours that defaults to 6.',starter:"where event_ts >= dateadd(hour,-6,(select max(event_ts) from {{ this }}))",req:[['var('],['lookback_hours'],['6']],anti:[],why:[['config','parameter','environment'],['avoid hard code']],ref:"where event_ts >= dateadd(\n  hour,\n  -1 * {{ var('lookback_hours', 6) }},\n  (select max(event_ts) from {{ this }})\n)"},
    {id:'j5',title:'Read environment value safely',level:'Intermediate',prompt:'Read DBT_TARGET_ENV with env_var() and use it in a comment or conditional.',starter:"{% set env = 'prod' %}",req:[['env_var('],['DBT_TARGET_ENV']],anti:[['set env = \'prod\'','hard-coded environment']],why:[['environment','deploy'],['secret','config']],ref:"{% set env = env_var('DBT_TARGET_ENV', 'dev') %}\n-- target environment: {{ env }}"},
    {id:'j6',title:'Create safe_divide macro',level:'Intermediate',prompt:'Write a Jinja macro safe_divide(numerator, denominator) that returns NULL when denominator is zero.',starter:"{% macro safe_divide(numerator, denominator) %}\n  {{ numerator }} / {{ denominator }}\n{% endmacro %}",req:[['macro safe_divide'],['case'],['when'],['= 0'],['null'],['numerator'],['denominator']],anti:[],why:[['reuse','consistent'],['zero','division']],ref:"{% macro safe_divide(numerator, denominator) %}\ncase\n  when {{ denominator }} = 0 then null\n  else {{ numerator }} / {{ denominator }}\nend\n{% endmacro %}"},
    {id:'j7',title:'Use a macro in a model',level:'Intermediate',prompt:'Call safe_divide to calculate revenue_per_visit from net_revenue and visits.',starter:"select net_revenue / visits as revenue_per_visit from {{ ref('fct_property_day') }}",req:[['safe_divide('],['net_revenue'],['visits']],anti:[['net_revenue / visits','bypasses shared macro']],why:[['consistent','reuse','semantic'],['zero']],ref:"select\n  {{ safe_divide('net_revenue', 'visits') }} as revenue_per_visit\nfrom {{ ref('fct_property_day') }}"},
    {id:'j8',title:'Generate pivot columns with a for loop',level:'Advanced',prompt:'Generate amount columns for cash, credit and points using one Jinja for loop.',starter:"select\n  sum(case when payment_method='cash' then amount else 0 end) cash_amount\nfrom {{ ref('fct_payments') }}",req:[['for payment_method'],['cash'],['credit'],['points'],['loop.last'],['endfor']],anti:[],why:[['dry','repeat','generate'],['compile to sql']],ref:"select\n{% for payment_method in ['cash','credit','points'] %}\n  sum(case when payment_method='{{ payment_method }}' then amount else 0 end) as {{ payment_method }}_amount{% if not loop.last %},{% endif %}\n{% endfor %}\nfrom {{ ref('fct_payments') }}"},
    {id:'j9',title:'Environment-aware sample window',level:'Advanced',prompt:'Use target.name so dev processes 3 days and prod processes 30 days.',starter:"where event_date >= current_date - 3",req:[['target.name'],['prod'],['30'],['3'],['if'],['else']],anti:[],why:[['environment','dev','prod'],['cost','sample']],ref:"{% if target.name == 'prod' %}\nwhere event_date >= current_date - 30\n{% else %}\nwhere event_date >= current_date - 3\n{% endif %}"},
    {id:'j10',title:'Reusable cents_to_dollars macro',level:'Intermediate',prompt:'Write a macro that converts a numeric cents expression to a decimal dollar value.',starter:"{% macro cents_to_dollars(column_name) %}\n{{ column_name }} / 100\n{% endmacro %}",req:[['macro cents_to_dollars'],['column_name'],['100'],['cast','decimal','number']],anti:[],why:[['reuse','standard'],['type','precision']],ref:"{% macro cents_to_dollars(column_name, scale=2) %}\ncast({{ column_name }} / 100.0 as number(18, {{ scale }}))\n{% endmacro %}"},
    {id:'j11',title:'Config-driven incremental merge',level:'Advanced',prompt:'Configure an incremental model using merge strategy and unique_key reward_id.',starter:"{{ config(materialized='table') }}",req:[['materialized'],['incremental'],['unique_key'],['reward_id'],['incremental_strategy'],['merge']],anti:[['materialized=\'table\'','full rebuild']],why:[['merge','idempot','incremental'],['unique key']],ref:"{{ config(\n  materialized='incremental',\n  unique_key='reward_id',\n  incremental_strategy='merge'\n) }}"},
    {id:'j12',title:'Generate a surrogate-key expression',level:'Advanced',prompt:'Use dbt_utils.generate_surrogate_key over source_system and event_id.',starter:"select source_system || '-' || event_id as event_key",req:[['dbt_utils.generate_surrogate_key'],['source_system'],['event_id']],anti:[['||','manual concatenation collision risk']],why:[['deterministic','key'],['null','separator','reuse']],ref:"select {{ dbt_utils.generate_surrogate_key(['source_system','event_id']) }} as event_key"},
    {id:'j13',title:'Conditional column generation',level:'Advanced',prompt:'Loop over quality dimensions completeness, validity and uniqueness to generate *_failed flags.',starter:"select * from base",req:[['for dim'],['completeness'],['validity'],['uniqueness'],['endfor'],['_failed']],anti:[],why:[['generate','repeated'],['consistent','quality']],ref:"select\n{% for dim in ['completeness','validity','uniqueness'] %}\n  case when {{ dim }}_score < 1 then 1 else 0 end as {{ dim }}_failed{% if not loop.last %},{% endif %}\n{% endfor %}\nfrom base"},
    {id:'j14',title:'Macro with adapter-aware dispatch concept',level:'Principal',prompt:'Create a wrapper macro normalize_timestamp(expr) that delegates through adapter.dispatch so warehouses can specialize implementation.',starter:"{% macro normalize_timestamp(expr) %}\n  cast({{ expr }} as timestamp)\n{% endmacro %}",req:[['adapter.dispatch'],['normalize_timestamp'],['expr']],anti:[],why:[['portability','adapter','warehouse'],['dispatch']],ref:"{% macro normalize_timestamp(expr) %}\n  {{ return(adapter.dispatch('normalize_timestamp', 'opsready')(expr)) }}\n{% endmacro %}\n\n{% macro default__normalize_timestamp(expr) %}\n  cast({{ expr }} as timestamp)\n{% endmacro %}"},
    {id:'j15',title:'Avoid unsafe dynamic SQL identifiers',level:'Principal',prompt:'Generate metrics only from an allowlisted list rather than interpolating arbitrary user input into SQL identifiers.',starter:"{% set metric = var('metric_name') %}\nselect {{ metric }} from {{ ref('fct_daily') }}",req:[['allowed','allowlist','metrics'],['if'],['metric'],['exceptions.raise_compiler_error','raise_compiler_error']],anti:[],why:[['allowlist','injection','governance'],['compiler error','fail']],ref:"{% set metric = var('metric_name') %}\n{% set allowed_metrics = ['net_revenue','visits','active_players'] %}\n{% if metric not in allowed_metrics %}\n  {{ exceptions.raise_compiler_error('Unsupported metric: ' ~ metric) }}\n{% endif %}\nselect {{ metric }} from {{ ref('fct_daily') }}"}
  ];

  const agents = [
    {name:'Data Ingestion & Schema-Drift Agent',domain:'Ingestion',purpose:'Detect contract drift, classify compatibility and route bad records without corrupting accepted data.',trigger:'New schema/version or parse-failure anomaly',tools:['Schema registry/contract metadata','Bronze/raw samples','Quarantine writer','Lineage catalog'],outputs:['Compatibility decision','Quarantine set','Impact report','Proposed mapping'],allowed:['Read schemas and samples','Quarantine incompatible records','Open incident/change request'],approval:['Promote breaking schema mapping','Backfill affected history'],forbidden:['Drop raw evidence','Silently coerce financial fields']},
    {name:'Live ETL Orchestrator',domain:'Streaming',purpose:'Observe pipeline state and coordinate approved bounded recovery steps across streaming dependencies.',trigger:'Lag, failed micro-batch, stalled sink or SLA breach',tools:['Kafka metrics','Databricks job API','Checkpoint metadata','Snowflake task status'],outputs:['Constraint localization','Recovery plan','Bounded replay request'],allowed:['Read telemetry','Pause bounded publication','Restart approved stateless step'],approval:['Checkpoint recovery','Replay interval expansion'],forbidden:['Delete checkpoint before evidence','Scale every layer blindly']},
    {name:'Data Quality & Profiling Auditor',domain:'Quality',purpose:'Profile completeness, validity, duplicates, distribution shifts and control totals.',trigger:'Batch/stream checkpoint completed or quality SLO breach',tools:['SQL controls','dbt tests','Profiler','Reconciliation tables'],outputs:['Acceptance recommendation','Residual classification','Quality evidence'],allowed:['Run tests and controls','Block publication gate','Create defect ticket'],approval:['Approve exceptional adjustment'],forbidden:['Modify source facts to make tests pass']},
    {name:'Enterprise Semantic Layer Guardian',domain:'Semantics',purpose:'Protect metric definitions, grain and governed analytical contracts.',trigger:'Metric/model change, conflicting dashboard result',tools:['dbt manifest','Semantic definitions','Lineage','Query history'],outputs:['Metric impact analysis','Definition conflict','Migration guidance'],allowed:['Read/compare definitions','Block incompatible semantic release'],approval:['Change enterprise metric contract'],forbidden:['Redefine financial metric autonomously']},
    {name:'Data Privacy & Masking Compliance Officer',domain:'Security',purpose:'Detect sensitive data exposure and validate masking, retention and least-privilege controls.',trigger:'New field, role change, policy scan or access anomaly',tools:['Catalog classifications','RBAC metadata','Masking policies','Audit logs'],outputs:['Exposure finding','Policy recommendation','Access review'],allowed:['Read policy metadata','Flag/revoke pre-approved temporary exposure'],approval:['Role-policy changes','Deletion/retention actions'],forbidden:['Grant itself elevated roles','Expose raw PII in prompts']},
    {name:'FinOps & Compute Optimization Agent',domain:'FinOps',purpose:'Find waste and performance pathologies before recommending more compute.',trigger:'Credit/cost anomaly, slow query or idle resource',tools:['Snowflake query profile','Warehouse history','Spark metrics','Cost tags'],outputs:['Root-cause cost report','Optimization plan','Right-sizing recommendation'],allowed:['Analyze profiles','Recommend suspend/right-size','Open optimization PR'],approval:['Resize production critical compute'],forbidden:['Scale blindly without causal evidence']},
    {name:'Conversational Analytics Insights Agent',domain:'Analytics',purpose:'Answer natural-language questions through governed semantic views with read-only tools.',trigger:'User question',tools:['Approved semantic layer','SELECT-only SQL tool','Metric dictionary'],outputs:['Answer','SQL/evidence','Metric citations'],allowed:['SELECT approved views','Explain metrics'],approval:['Access restricted datasets'],forbidden:['DML/DDL','Use admin role','Invent metric definition']},
    {name:'Incident Self-Healing Pipeline Agent',domain:'Reliability',purpose:'Contain incidents, preserve evidence, execute low-risk runbook actions and escalate high-impact recovery.',trigger:'SEV alert or acceptance-gate failure',tools:['Runbooks','Observability','Deployment API','Publication gate'],outputs:['Containment action','Timeline','Recovery recommendation','Handoff'],allowed:['Pause publication','Preserve evidence','Run diagnostics','Rollback approved release'],approval:['Bulk replay','Financial correction','Customer-impacting mutation'],forbidden:['Delete evidence','Reverse rewards autonomously']},
    {name:'Metadata & Data Cataloging Automator',domain:'Governance',purpose:'Capture lineage, ownership, descriptions and change metadata from engineering artifacts.',trigger:'Merge/deploy/new dataset',tools:['dbt manifest','Spark lineage','Git metadata','Catalog API'],outputs:['Catalog updates','Ownership gaps','Lineage graph'],allowed:['Update descriptive metadata','Open stewardship tasks'],approval:['Change legal classification/retention class'],forbidden:['Fabricate lineage','Change business owner silently']}
  ];
  const models = [
    {name:'Omni-Channel Dynamic Pricing',goal:'Optimize approved offer/price decisions across channels within policy bounds.',features:'demand, inventory, channel, seasonality, elasticity',risk:'price fairness, policy constraints, feedback loops',agent:'FinOps & Compute Optimization Agent'},
    {name:'Next-Best-Action Hyper-Personalization',goal:'Rank eligible customer actions/offers with governed eligibility.',features:'profile, recency, affinity, context, eligibility',risk:'stale eligibility, leakage, treatment policy',agent:'Conversational Analytics Insights Agent'},
    {name:'High-Value Player Churn Mitigation',goal:'Estimate churn risk and prioritize permitted retention interventions.',features:'visit cadence, spend, engagement, service signals',risk:'calibration drift, intervention capacity, privacy',agent:'Data Quality & Profiling Auditor'},
    {name:'Predictive Casino Floor Maintenance',goal:'Predict equipment failure risk to schedule maintenance before outage.',features:'telemetry, error codes, utilization, maintenance history',risk:'false alarms, sensor drift, maintenance capacity',agent:'Live ETL Orchestrator'},
    {name:'Labor & Footfall Forecasting',goal:'Forecast guest traffic and staffing demand by property/time.',features:'bookings, events, historical footfall, seasonality',risk:'event shocks, bias, labor constraints',agent:'Enterprise Semantic Layer Guardian'},
    {name:'Geolocation & Digital Fraud Detection',goal:'Score anomalous access/transaction behavior for review or bounded blocks.',features:'location, device, velocity, network, account history',risk:'false positives, review capacity, threshold drift',agent:'Incident Self-Healing Pipeline Agent'}
  ];
  const drills = [
    {id:'d1',title:'Breaking amount schema',sev:'SEV2',prompt:'POS amount changes DECIMAL → VARCHAR and 7.4% of events fail parsing.',agent:'Data Ingestion & Schema-Drift Agent',actions:['Silently cast every value','Quarantine incompatible records and preserve raw','Drop the new field','Scale Snowflake'],correct:'Quarantine incompatible records and preserve raw',why:[['schema','contract','quarantine'],['preserve','raw'],['approval','mapping']]},
    {id:'d2',title:'Reward duplication in progress',sev:'SEV1',prompt:'842 duplicate rewards are actively being created after a replay.',agent:'Incident Self-Healing Pipeline Agent',actions:['Delete checkpoint immediately','Contain reward publication and preserve evidence','Reverse all rewards automatically','Wait for lag to drain'],correct:'Contain reward publication and preserve evidence',why:[['contain','publication'],['evidence','checkpoint','offset'],['approval','financial']]},
    {id:'d3',title:'Warehouse cost spike',sev:'SEV2',prompt:'Snowflake credits triple; one query scans 24 TB for one day/property.',agent:'FinOps & Compute Optimization Agent',actions:['Scale to 4XL','Inspect query profile and pruning before scaling','Disable auto-suspend','Ignore cost until month-end'],correct:'Inspect query profile and pruning before scaling',why:[['profile','pruning'],['cost','credits'],['scale','after']]},
    {id:'d4',title:'Conflicting net revenue',sev:'SEV2',prompt:'Finance shows $8.2M while Operations shows $8.7M for the same period.',agent:'Enterprise Semantic Layer Guardian',actions:['Average the numbers','Compare metric definitions, grain and adjustment rules','Pick Finance because it is smaller','Grant analysts write access'],correct:'Compare metric definitions, grain and adjustment rules',why:[['metric','definition'],['grain','adjustment'],['semantic','govern']]},
    {id:'d5',title:'PII appears in analytics prompt trace',sev:'SEV1',prompt:'A natural-language analytics request logged raw customer email and phone.',agent:'Data Privacy & Masking Compliance Officer',actions:['Ignore because it is internal','Contain exposure, inspect policy/log path and rotate access if needed','Train model on the trace','Grant agent admin'],correct:'Contain exposure, inspect policy/log path and rotate access if needed',why:[['pii','privacy','mask'],['contain','audit','access'],['approval','policy']]},
    {id:'d6',title:'Kafka lag with hot partition',sev:'SEV2',prompt:'Lag is 1.8M and partition 7 has 43% of traffic.',agent:'Live ETL Orchestrator',actions:['Add consumers only','Inspect key distribution and constrained stage','Delete topic','Scale Snowflake'],correct:'Inspect key distribution and constrained stage',why:[['partition','key','skew'],['lag','throughput'],['evidence','consumer']]},
    {id:'d7',title:'Quality count balances but IDs differ',sev:'SEV2',prompt:'Source and target counts match, but 17 target-only reward IDs exist.',agent:'Data Quality & Profiling Auditor',actions:['Pass because counts match','Run key-level reconciliation and block publication','DISTINCT the target','Delete target-only rows without investigation'],correct:'Run key-level reconciliation and block publication',why:[['key','reconciliation'],['count','not enough'],['block','publication']]},
    {id:'d8',title:'Executive asks ad-hoc KPI question',sev:'SEV3',prompt:'Executive asks: “Why did net gaming revenue fall yesterday?” using approved metrics only.',agent:'Conversational Analytics Insights Agent',actions:['Use read-only semantic SQL and cite metric definitions','Give agent ACCOUNTADMIN','Create new metric definition silently','Write an adjustment to revenue'],correct:'Use read-only semantic SQL and cite metric definitions',why:[['read only','select'],['semantic','metric'],['cite','definition']]},
    {id:'d9',title:'Dataset shipped without owner/lineage',sev:'SEV3',prompt:'A new Gold model deployed but catalog ownership and upstream lineage are blank.',agent:'Metadata & Data Cataloging Automator',actions:['Extract manifest/Git lineage and open ownership gap','Delete the model','Invent an owner','Ignore metadata'],correct:'Extract manifest/Git lineage and open ownership gap',why:[['lineage','manifest','git'],['owner','catalog'],['do not invent','steward']]},
    {id:'d10',title:'Fraud review queue explodes',sev:'SEV2',prompt:'Fraud model flags 7,500/day while human review capacity is 500/day.',agent:'Data Quality & Profiling Auditor',actions:['Auto-ban all 7,500','Assess drift/calibration and threshold against review capacity','Turn model off permanently','Increase confidence text in prompt'],correct:'Assess drift/calibration and threshold against review capacity',why:[['drift','calibration'],['threshold','capacity'],['human review','approval']]},
    {id:'d11',title:'Agent proposes 2,400 reward reversals',sev:'SEV1',prompt:'Self-healing agent has high confidence that 2,400 rewards are wrong and proposes bulk reversal.',agent:'Incident Self-Healing Pipeline Agent',actions:['Execute automatically','Require authorized human approval after evidence/reconciliation','Delete audit logs','Ask conversational agent to decide'],correct:'Require authorized human approval after evidence/reconciliation',why:[['approval','human'],['financial','customer'],['reconciliation','evidence']]},
    {id:'d12',title:'Model serving feature freshness breach',sev:'SEV2',prompt:'Next-best-action model uses features 45 minutes old; contract is 10 minutes.',agent:'Live ETL Orchestrator',actions:['Contain stale scoring/publication and trace feature pipeline freshness','Increase model temperature','Ignore because model endpoint is healthy','Retrain immediately without diagnosis'],correct:'Contain stale scoring/publication and trace feature pipeline freshness',why:[['feature','freshness'],['pipeline','upstream'],['contain','stale']]}
  ];

  const patternDomains=['Ingestion','Streaming','Quality','Snowflake','Databricks','dbt','API','Security','FinOps','Observability','Metadata','ML Ops','Semantic Layer','Reliability','CI/CD','Customer 360'];
  const patternRoles=['Contract Validator','Replay Controller','Freshness Sentinel','Cardinality Auditor','Reconciliation Analyst','Lineage Mapper','Cost Investigator','Schema Profiler','SLA Guardian','Backfill Planner','Access Reviewer','Drift Monitor','Feature Consistency Checker','Deployment Verifier','Runbook Navigator','Serving Health Analyst'];
  const toolsByDomain={Ingestion:'schema registry + object storage',Streaming:'Kafka + Structured Streaming',Quality:'SQL controls + dbt tests',Snowflake:'query history + tasks',Databricks:'Spark metrics + Delta',dbt:'manifest + tests',API:'OpenAPI + telemetry',Security:'RBAC + audit logs',FinOps:'cost history + profiles',Observability:'metrics + logs + traces',Metadata:'catalog + lineage','ML Ops':'MLflow + feature metadata','Semantic Layer':'metric registry + lineage',Reliability:'runbooks + incident state','CI/CD':'Git + pipeline checks','Customer 360':'identity graph + governed marts'};
  const library = agents.map((a,i)=>({name:a.name,domain:a.domain,role:'Core production agent',level:'Proficiency',tool:a.tools.join(', '),evidence:a.outputs.join(', '),autonomy:'Bounded'}));
  outer: for(const d of patternDomains){for(const r of patternRoles){if(library.length>=127)break outer;const idx=library.length;library.push({name:`${d} ${r} Agent`,domain:d,role:r,level:idx<75?'Proficiency':'Exposure',tool:toolsByDomain[d]||'governed tools',evidence:'typed output + audit trail + acceptance evidence',autonomy:['Read-only','Bounded write','Approval-gated'][idx%3]})}}
  while(library.length<127){const idx=library.length;library.push({name:`Enterprise Control Pattern ${idx+1} Agent`,domain:'Governance',role:'Control pattern',level:idx<75?'Proficiency':'Exposure',tool:'catalog + policy + evidence store',evidence:'decision record + audit trail',autonomy:'Approval-gated'})}

  let archIndex=0,jinjaIndex=0,drillIndex=0;
  function nav(){document.querySelectorAll('#tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#tabs button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('main>.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active');if(b.dataset.tab==='scorecard')renderScorecard()})}
  function chips(...items){return items.map(x=>`<span>${esc(x)}</span>`).join('')}
  function renderArchList(){const h=$('archList');h.innerHTML='';architecture.forEach((x,i)=>{const b=document.createElement('button');const best=state.best.Architecture[x.id]||0;b.className=(i===archIndex?'active ':'')+(best>=85?'pass':'');b.innerHTML=`<b>${i+1}. ${esc(x.title)}</b><small>${esc(x.domain)}${best?' • best '+best+'%':''}</small>`;b.onclick=()=>{archIndex=i;renderArch()};h.appendChild(b)})}
  function renderArch(){const x=architecture[archIndex];renderArchList();$('archMeta').innerHTML=chips(x.domain,'Why vs alternatives','Proof required');$('archTitle').textContent=x.title;$('archPrompt').textContent=x.prompt;$('archChoice').innerHTML='<option value="">Choose...</option>'+x.choices.map(c=>`<option>${esc(c)}</option>`).join('');$('archWhy').value='';$('archWhyNot').value='';$('archTradeoff').value='';$('archProof').value='';$('archFeedback').className='feedback';$('archFeedback').textContent='Defend the decision. Correct tool selection alone earns only 40%.'}
  function archGrade(){const x=architecture[archIndex],choice=$('archChoice').value;const a=choice===x.correct?40:0,w=keywordScore($('archWhy').value,x.why,15),n=keywordScore($('archWhyNot').value,x.whyNot,15),t=keywordScore($('archTradeoff').value,x.trade,15),p=keywordScore($('archProof').value,x.proof,15),score=a+w+n+t+p;const cls=score>=85?'pass':score>=65?'partial':'fail';$('archFeedback').className='feedback '+cls;$('archFeedback').innerHTML=`<strong>${score}%</strong> — Tool ${a}/40 • Why ${w}/15 • Why-not ${n}/15 • Tradeoff ${t}/15 • Proof ${p}/15<div class="refbox"><b>Reference:</b> ${esc(x.ref)}</div>`;record('Architecture',x.id,x.title,score,`tool ${a}/40; reasoning ${w+n+t+p}/60`);renderArchList()}
  function archRef(){const x=architecture[archIndex];$('archFeedback').className='feedback';$('archFeedback').innerHTML=`<div class="refbox"><b>Reference decision:</b> ${esc(x.correct)}<br>${esc(x.ref)}</div>`}

  function renderJinjaList(){const h=$('jinjaList');h.innerHTML='';jinja.forEach((x,i)=>{const b=document.createElement('button'),best=state.best.Jinja[x.id]||0;b.className=(i===jinjaIndex?'active ':'')+(best>=85?'pass':'');b.innerHTML=`<b>${i+1}. ${esc(x.title)}</b><small>${esc(x.level)}${best?' • best '+best+'%':''}</small>`;b.onclick=()=>{jinjaIndex=i;renderJinja()};h.appendChild(b)})}
  function renderJinja(){const x=jinja[jinjaIndex];renderJinjaList();$('jinjaMeta').innerHTML=chips(x.level,'Jinja','dbt compile reasoning');$('jinjaTitle').textContent=x.title;$('jinjaPrompt').textContent=x.prompt;$('jinjaCode').value=x.starter;$('jinjaWhy').value='';$('jinjaOutput').textContent='Ready.';$('jinjaRubric').innerHTML=''}
  function gradeJinja(){const x=jinja[jinjaIndex],code=$('jinjaCode').value,why=$('jinjaWhy').value;let rows=[],earned=0;const per=x.req.length?70/x.req.length:70;x.req.forEach(g=>{const ok=hasAny(code,g);if(ok)earned+=per;rows.push({ok,label:'Required: '+g.join(' / ')})});let penalty=0;x.anti.forEach(([needle,label])=>{if(norm(code).includes(norm(needle))){penalty+=10;rows.push({ok:false,label:'Anti-pattern: '+label})}});const whyPts=keywordScore(why,x.why,30);let score=Math.max(0,Math.min(100,Math.round(earned)+whyPts-penalty));$('jinjaOutput').textContent=(score>=85?'COMPILE / PATTERN PASS':'NEEDS WORK')+`\nScore ${score}%\nCode pattern ${Math.round(earned)}/70\nReasoning ${whyPts}/30\nPenalty ${penalty}`;$('jinjaRubric').innerHTML=rows.map(r=>`<div class="rubric-row ${r.ok?'ok':'bad'}"><b>${r.ok?'✓':'✗'}</b><span>${esc(r.label)}</span></div>`).join('')+`<div class="refbox"><b>Reference:</b><pre>${esc(x.ref)}</pre></div>`;record('Jinja',x.id,x.title,score,`code ${Math.round(earned)}/70; why ${whyPts}/30`);renderJinjaList()}

  function renderAgents(){const h=$('agentCards');h.innerHTML='';agents.forEach((a,i)=>{const c=document.createElement('div');c.className='card'+(i===0?' active':'');c.innerHTML=`<span class="pill">${esc(a.domain)}</span><h3>${esc(a.name)}</h3><p>${esc(a.purpose)}</p>`;c.onclick=()=>{document.querySelectorAll('#agentCards .card').forEach(x=>x.classList.remove('active'));c.classList.add('active');renderAgentDetail(a)};h.appendChild(c)});renderAgentDetail(agents[0]);const m=$('modelCards');m.innerHTML='';models.forEach(x=>{const c=document.createElement('div');c.className='card';c.innerHTML=`<span class="pill">ML System</span><h3>${esc(x.name)}</h3><p><b>Goal:</b> ${esc(x.goal)}</p><p><b>Features:</b> ${esc(x.features)}</p><p><b>Risk:</b> ${esc(x.risk)}</p><p><b>Operational partner:</b> ${esc(x.agent)}</p>`;m.appendChild(c)})}
  function renderAgentDetail(a){$('agentDetail').innerHTML=`<div class="meta">${chips(a.domain,'Bounded automation')}</div><h2>${esc(a.name)}</h2><p>${esc(a.purpose)}</p><p><b>Trigger:</b> ${esc(a.trigger)}</p><p><b>Tools:</b> ${esc(a.tools.join(' • '))}</p><p><b>Outputs:</b> ${esc(a.outputs.join(' • '))}</p><h3>Authority boundary</h3><div class="authority">${a.allowed.map(x=>`<div class="yes"><b>Allowed</b><br>${esc(x)}</div>`).join('')}${a.approval.map(x=>`<div class="approval"><b>Approval-gated</b><br>${esc(x)}</div>`).join('')}${a.forbidden.map(x=>`<div class="no"><b>Forbidden</b><br>${esc(x)}</div>`).join('')}</div><div class="refbox"><b>Invariant:</b> Agents may interpret and coordinate, but business-critical mutations remain deterministic, observable, idempotent and approval-bounded.</div>`}

  function renderDrillList(){const h=$('agentDrillList');h.innerHTML='';drills.forEach((x,i)=>{const b=document.createElement('button'),best=state.best.AgentDrills[x.id]||0;b.className=(i===drillIndex?'active ':'')+(best>=85?'pass':'');b.innerHTML=`<b>${i+1}. ${esc(x.title)}</b><small>${esc(x.sev)}${best?' • best '+best+'%':''}</small>`;b.onclick=()=>{drillIndex=i;renderDrill()};h.appendChild(b)})}
  function renderDrill(){const x=drills[drillIndex];renderDrillList();$('drillMeta').innerHTML=chips(x.sev,'Agent selection','Authority boundary');$('drillTitle').textContent=x.title;$('drillPrompt').textContent=x.prompt;$('drillAgent').innerHTML='<option value="">Choose...</option>'+agents.map(a=>`<option>${esc(a.name)}</option>`).join('');$('drillAction').innerHTML='<option value="">Choose...</option>'+x.actions.map(a=>`<option>${esc(a)}</option>`).join('');$('drillWhy').value='';$('drillFeedback').className='feedback';$('drillFeedback').textContent='Choose the agent and safe next action, then explain the authority boundary.'}
  function gradeDrill(){const x=drills[drillIndex];const a=$('drillAgent').value===x.agent?40:0,b=$('drillAction').value===x.correct?35:0,r=keywordScore($('drillWhy').value,x.why,25),score=a+b+r;$('drillFeedback').className='feedback '+(score>=85?'pass':score>=65?'partial':'fail');$('drillFeedback').innerHTML=`<strong>${score}%</strong> — Agent ${a}/40 • Action ${b}/35 • Governance reasoning ${r}/25<div class="refbox"><b>Reference:</b> ${esc(x.agent)} → ${esc(x.correct)}. High-impact financial, customer, security or compliance actions require explicit authorization and evidence.</div>`;record('AgentDrills',x.id,x.title,score,`agent ${a}/40; action ${b}/35; governance ${r}/25`);renderDrillList()}

  function renderLibrary(){const domains=[...new Set(library.map(x=>x.domain))].sort();$('agentDomain').innerHTML='<option value="all">All domains</option>'+domains.map(d=>`<option>${esc(d)}</option>`).join('');filterLibrary()}
  function filterLibrary(){const q=norm($('agentSearch').value),level=$('agentLevel').value,domain=$('agentDomain').value;const arr=library.filter(x=>(!q||norm(Object.values(x).join(' ')).includes(q))&&(level==='all'||x.level===level)&&(domain==='all'||x.domain===domain));$('libraryStats').innerHTML=`<span>${arr.length} shown</span><span>127 total</span><span>75 proficiency</span><span>52 exposure</span>`;$('agentLibrary').innerHTML=arr.map(x=>`<article class="library-item"><span class="pill">${esc(x.level)}</span><h4>${esc(x.name)}</h4><p>${esc(x.domain)} • ${esc(x.role)}</p><p><b>Tooling:</b> ${esc(x.tool)}</p><p><b>Evidence:</b> ${esc(x.evidence)}</p><p><b>Autonomy:</b> ${esc(x.autonomy)}</p></article>`).join('')}

  function metricsFor(lab,total){const vals=Object.values(state.best[lab]||{});return {attempted:vals.length,avg:vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0,best:vals.length?Math.max(...vals):0,total}}
  function renderMaster(){const m=[metricsFor('Architecture',24),metricsFor('Jinja',15),metricsFor('AgentDrills',12)];const attempted=m.reduce((a,b)=>a+b.attempted,0),weighted=m.reduce((a,b)=>a+(b.avg||0),0),cats=m.filter(x=>x.attempted).length,score=cats?Math.round(weighted/cats):0;$('masterScore').textContent=score+'%';$('masterSub').textContent=attempted?`${attempted}/51 graded scenarios attempted`:'No graded evidence yet'}
  function renderScorecard(){const sets=[['Architecture Decisions','Architecture',24],['Jinja Mastery','Jinja',15],['Agent Decision Drills','AgentDrills',12]];$('scoreMetrics').innerHTML=sets.map(([label,key,total])=>{const m=metricsFor(key,total);return `<div class="score-card"><span>${esc(label)}</span><strong>${m.avg||0}%</strong><small>${m.attempted}/${total} attempted • best ${m.best||0}%</small></div>`}).join('')+`<div class="score-card"><span>127-Agent Library</span><strong>127</strong><small>75 proficiency • 52 exposure patterns</small></div>`;$('historyBody').innerHTML=state.history.slice().reverse().slice(0,20).map(x=>`<tr><td>${esc(x.lab)}</td><td>${esc(x.title)}</td><td>${x.score}%</td><td>${esc(x.detail)}</td><td>${new Date(x.at).toLocaleString()}</td></tr>`).join('')||'<tr><td colspan="5">No V4 attempts yet.</td></tr>'}

  nav();renderArch();renderJinja();renderAgents();renderDrill();renderLibrary();renderMaster();renderScorecard();
  $('gradeArch').onclick=archGrade;$('loadArchRef').onclick=archRef;$('gradeJinja').onclick=gradeJinja;$('loadJinjaRef').onclick=()=>{$('jinjaCode').value=jinja[jinjaIndex].ref};$('gradeAgentDrill').onclick=gradeDrill;$('showDrillRef').onclick=()=>{$('drillFeedback').innerHTML=`<div class="refbox"><b>${esc(drills[drillIndex].agent)}</b> → ${esc(drills[drillIndex].correct)}</div>`};$('agentSearch').oninput=filterLibrary;$('agentLevel').onchange=filterLibrary;$('agentDomain').onchange=filterLibrary;
})();